const { execSync } = require('child_process');
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const ts = new Date().toISOString();
let out = '';
let err_count = 0;
try { out = execSync(`"${prj}/IMPAR_OS/bin/impar-os" repair 2>&1`, {timeout:30000}).toString(); } catch(e) { out = e.message; err_count++; }
return [{ json: { status: err_count === 0 ? 'ok' : 'partial', ai_used: false, timestamp: ts, output: out.substring(0,1000), safe_only: true } }];
